entries.commands:
# ===== 端口聚合（FortiOS）=====
config system interface
    edit "{{agg_name}}"
        set vdom "root"
        set type aggregate
        set member {{member_ports}}
        set lacp-mode {{lacp_mode}}
        set vlanforward enable
        set description "{{agg_desc}}"
    next
end
show system interface {{agg_name}}
diagnose netlink aggregate name {{agg_name}}

# ===== 静态路由（FortiOS）=====
config router static
    edit {{seq}}
        set dst {{dest_net}} {{dest_mask}}
        set gateway {{gateway}}
        set device "{{out_interface}}"
        set distance {{distance}}
        set comment "{{comment}}"
    next
    edit {{default_seq}}
        set dst 0.0.0.0 0.0.0.0
        set gateway {{gateway}}
        set device "{{out_interface}}"
        set distance {{default_distance}}
    next
end
show router static
get router info routing-table all

# ===== 配置查看与本地备份（FortiOS）=====
show full-configuration
execute backup config flash {{backup_name}}
diagnose sys flash list
# 插了 U 盘时可以直接备份到 U 盘（现场最常用）
# execute backup config usb {{backup_name}}
# 恢复配置（会覆盖当前配置，务必确认）
# execute restore config flash {{backup_name}}

entries.rollback:
# 回退：本条目仅备份配置到 flash，不改变网络行为，无需配置回退；
# 需要恢复配置时（★ 覆盖当前配置并重启，务必确认后再执行）
execute restore config flash {{backup_name}}

# 回退：删除入向策略（VIP 对象保留，外网发布立即中断）
config firewall policy
    delete {{policy_id}}
end
# 复核（期望无该策略）
show firewall policy | grep {{policy_name}}

entries.commands:
# ===== 1) 建自定义服务（TCP）=====
config firewall service custom
    edit "{{svc_name}}"
        set protocol {{protocol}}
        set tcp-portrange {{port_range}}
        set comment "{{svc_comment}}"
    next
end
# UDP 服务改成：set protocol UDP / set udp-portrange {{port_range}}
# ===== 2) 复核 =====
show firewall service custom {{svc_name}}

# ===== 1) 查看指定策略计数（100004 = IPv4 防火墙策略表）=====
diagnose firewall iprope show 100004 {{policy_id}}
# ===== 2) 清零该策略计数（只清统计，不动配置）=====
diagnose firewall iprope clear 100004 {{policy_id}}
# ===== 3) 复核（计数从 0 起算）=====
diagnose firewall iprope show 100004 {{policy_id}}

entries.rollback:
# 计数清零不可逆（清零前数值不保留）；清零前先留证：
diagnose firewall iprope show 100004 {{policy_id}}
# 若需保存，把上面输出贴入变更单或截图归档
